/* ═════════════════════════════════════════════════════════════════
   CITY SOCCER CLUB — PORTEKİZCE (Brezilya) SÖZLÜK  (pt)

   Anahtar = oyunda geçen Türkçe metnin BİREBİR kendisi.
   Burada olmayan her şey (oyuncu adı, takım adı, sohbet) olduğu gibi kalır.
   Bu dosya index.html tarafından, YALNIZCA dil Portekizce ise indirilir.
   Güncelleme yaparken index.html içindeki _i18nSozlukSurum değerini artır.
   ═════════════════════════════════════════════════════════════════ */
window.I18N = window.I18N || {};
window.I18N.pt = window.I18N.pt || {};
window.I18N_PATTERNS = window.I18N_PATTERNS || {};
window.I18N_PATTERNS.pt = window.I18N_PATTERNS.pt || [];

/* Desen içindeki alt metni çevirmek için: önce sözlük, sonra tam T(). */
window._i18nIcCevirPt = function (t) {
  if (window.I18N && window.I18N.pt && window.I18N.pt[t] != null) return window.I18N.pt[t];
  try { if (typeof window.T === 'function') { var r = window.T(t); if (r != null) return r; } } catch (e) {}
  return t;
};
var _icP = window._i18nIcCevirPt;

/* "A – B" düğümünde takım/ülke adını çevirir; baştaki-sondaki sayı ve işaretleri korur. */
window._i18nEsAdPt = function (s) {
  try {
    var m = String(s).match(/^([^A-Za-zÇĞİÖŞÜçğıöşü]*)([\s\S]*?)([^A-Za-zÇĞİÖŞÜçğıöşü]*)$/);
    if (!m || !m[2]) return s;
    return m[1] + _icP(m[2]) + m[3];
  } catch (e) { return s; }
};
var _esAdP = window._i18nEsAdPt;

