  "Antrenman, seçtiğin yeteneğe": "O treino, no atributo que você escolher,",
  "kazandırır; yetenek seviyen yükseldikçe oyuncu gücün (OVR) artar.": "dá pontos; conforme o nível do atributo sobe, sua força de jogador (OVR) aumenta.",
  ". İstediğin gruptan çalışabilirsin.": ". Você pode treinar o grupo que quiser.",
  ". Farklı gruba (Kaleci / Defans / Orta Saha / Forvet) geçişte": ". Ao mudar para outro grupo (Goleiro / Defesa / Meio-campo / Ataque)",
  "ve o grubun yeni yetenekleri 10'dan başlar.": "e os novos atributos desse grupo começam em 10.",
  "eşittir (Sv.1 → 1 eş zamanlı).": "é igual (Nv.1 → 1 simultâneo).",
  "ile başlarsın. Takım tesisin (Performans Merkezi) her seviye için": "para começar. A instalação do seu time (Centro de Performance) adiciona, por nível,",
  "harcama; hangisi önce dolarsa orada durur.": "de gasto; o que encher primeiro é o limite.",
  "işlenir, her bilet denetim için kaydedilir.": "é processado, e cada bilhete é registrado para auditoria.",
  "kazanır. Elmas ortalama her 200 bilette bir çıkar.": "ganha. Um diamante sai em média a cada 200 bilhetes.",
  "'de sıfırlanır. Kazanç tavanı Toto ile ortaktır.": "reinicia. O teto de ganhos é compartilhado com o Toto.",
  "Ücretsiz günlük bilet 25'e sayılmaz. Tüm sayaçlar": "O bilhete diário grátis não conta nos 25. Todos os contadores",
  "güncel sezon maaşı ÷ 4": "salário atual da temporada ÷ 4",
  "ve talep ettiğin": "e o solicitado",
  "(final galibi) ayrıca": "(o vencedor da final) também",
  "de buluşur. Final hariç tüm turlar çift maçlıdır.": "se enfrentam. Todas as fases, exceto a final, têm jogos de ida e volta.",
  ". Lig sonunda hak kazanan takımlar turnuvalara katılır.": ". Os times classificados ao fim da liga entram nos torneios.",
  "olarak katılacaksın. İstediğin zaman ayrılabilirsin.": "Você vai entrar como. Pode sair quando quiser.",
  ". Diğer üyeler oylarını veriyor.": ". Os outros membros estão votando.",
  ". Sonraki seçimde tekrar başvurabilirsin.": ". Você pode se candidatar de novo na próxima eleição.",
  "Karşı takım kaptanı kabul ederse maç planlanır.": "A partida é marcada se o capitão adversário aceitar.",
  "(Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)": "(Para tirar um jogador, arraste-o para as reservas na tela de escalação.)",
  ". Tüm takımlar, oyuncular ve maçlar kurgusaldır.": ". Todos os times, jogadores e partidas são fictícios.",
  ". Katılım yalnızca oyun içi sanal para ile yapılır;": ". A participação é feita só com moeda virtual do jogo;",
  ", kazanılan ödüller yalnızca oyun içinde kullanılır ve": ", os prêmios ganhos só podem ser usados no jogo e",
  ", oyuncunun yeteneklerinin ortalamasıdır ve": "é a média dos atributos do jogador e",
  "00:00'da sıfırlanır": "reinicia às 00:00",
