  "belirlenir: oyuncunun güncel yetenek seviyesine göre hesaplanır, oyuncu geliştikçe maaşı artar. Her maaş gününde": "é definido automaticamente: é calculado pelo nível de habilidade atual do jogador, então o salário sobe conforme ele evolui. Em cada dia de pagamento",
