  "eklenir. Transferler ve oyuncu maaşları finanstan ödenir. Bağış yaparak finansa kişisel destek verebilirsin.": "é adicionado. Transferências e salários dos jogadores são pagos pelas finanças. Você pode apoiar as finanças pessoalmente fazendo doações.",
  "‹ Geri": "‹ Voltar",
  "ANTRENMAN": "TREINO",
