  "Antrenman süresi uzadıkça kazanım artar, ama daha çok enerji ve süre ister.": "Treinos mais longos rendem mais, mas custam mais energia e tempo.",
  "Düzenli antrenman, takımdaki yerini ve transfer değerini yükseltmenin en hızlı yoludur.": "Treinar regularmente é o jeito mais rápido de subir no elenco e aumentar seu valor de transferência.",
  "Enerji sunucu saatiyle (UTC 00:00) yenilenir. Bu, her ülkede aşağıdaki yerel saate denk gelir:": "A energia é recarregada no horário do servidor (UTC 00:00). Isso corresponde ao seguinte horário local em cada país:",
