  "Kupon 5–15 maç · misli 5 – 5.000 € · kazanç tavanı 2.500.000 € · oran tavanı 500": "Bilhete 5–15 partidas · aposta 5 – 5.000 € · teto de prêmio 2.500.000 € · teto de odds 500",
  "belirlenir; kazıma yalnızca animasyondur. Sayfayı yenilesen sonuç değişmez.": "é definido com antecedência; raspar é só uma animação. Atualizar a página não muda o resultado.",
