  "Bu ülkede takım sahibi olan tüm kaptanlar otomatik olarak federasyon üyesidir. Sezon sonu seçimde her üyenin": "Todo capitão dono de um time neste país é automaticamente membro da federação. Na eleição de fim de temporada, cada membro tem",
