  "🏆 Pro görevler oyunun en büyük zaferleri — şampiyonluklar ve milli takım. Tek seferlik, kalıcı.": "🏆 Missões Pro são as maiores conquistas do jogo — títulos e seleção. Únicas e permanentes.",
