  "🏟️ Takımlar": "🏟️ Times",
  "💡 Diamond ile oyuncu transfer eder, tesis yükseltir, item ve takım satın alabilirsin. Büyük paketler kademeli bonus kazandırır.": "💡 Com diamantes você contrata jogadores, melhora instalações e compra itens ou times. Pacotes maiores dão bônus progressivamente maiores.",
  "2 sezon": "2 temporadas",
  "Aynısını tekrar yaz": "Digite novamente",
  "Beceri puanı maç motoruna ±%5 etki eder. Uzmanlık alanı belirli istatistiklere bonus verir.": "Pontos de habilidade afetam o motor de jogo em ±5%. A especialização dá bônus a certos atributos.",
  "Bonservis ve maaş sistemce belirlenmiştir. Maaş sezonun 10., 20., 30. ve 40. günlerinde 4 taksit halinde takım kasasından oyuncu cüzdanına ödenir.": "A taxa de transferência e o salário são definidos pelo sistema. O salário é pago do caixa do time para a carteira do jogador em 4 parcelas, nos dias 10, 20, 30 e 40 da temporada.",
