  "Hesabın için yeni bir şifre yaz.": "Escolha uma nova senha para sua conta.",
  "Hesabını silmek kalıcıdır. Takımın, oyuncun, cüzdanın ve tüm ilerlemen geri alınamaz şekilde kaldırılır.": "Excluir sua conta é permanente. Seu time, jogador, carteira e todo o progresso serão removidos de forma irreversível.",
  "Kupondan çıkar": "Remover do bilhete",
  "Opsiyonel. Onay verildiği an oyuncunun elmas cüzdanına aktarılır. Kasa elması (€ değil) kullanılır.": "Opcional. Transferido para a carteira de diamantes do jogador assim que for aprovado. Usa diamantes do caixa (não €).",
  "Oyuncu Transfer › Boştaki Oyuncular kısmına eklenecek. Yerine yeni bir oyuncu gelecek.": "O jogador será adicionado a Transferências › Jogadores livres. Um novo jogador ocupará o lugar dele.",
