  "Oyuncu hâlâ milli takım havuzunda kalır, daha sonra geri alabilirsin.": "O jogador continua no grupo da seleção; você pode trazê-lo de volta depois.",
  "Milli takımla kazanacağın ilk kupa burada görünecek. Önce kadroya davet edilmen, sonra eleme grubunu geçmen gerekir.": "Seu primeiro troféu com a seleção aparecerá aqui. Primeiro você precisa ser convocado, depois passar pelo grupo das eliminatórias.",
